const WeatherService={cacheKey:"advisoros_weather_cache",cacheTtlMs:18e5,async getTodayWeather(){const e=Utils.formatDate(Utils.getToday(),"iso");let t=null;try{t=JSON.parse(localStorage.getItem(this.cacheKey)||"null")}catch(e){}if(t&&t.dateKey===e&&Date.now()-t.fetchedAt<this.cacheTtlMs)return t.data;const r=await this.resolveCoords();if(!r)return t&&t.dateKey===e?t.data:null;try{const t=await this.fetchCurrent(r);return localStorage.setItem(this.cacheKey,JSON.stringify({dateKey:e,fetchedAt:Date.now(),data:t})),t}catch(r){return t&&t.dateKey===e?t.data:null}},async resolveCoords(){const e=CONFIG.businessLatLng;return Array.isArray(e)&&2===e.length&&Number.isFinite(e[0])&&Number.isFinite(e[1])?{lat:e[0],lng:e[1]}:e&&Number.isFinite(e.lat)&&Number.isFinite(e.lng)?{lat:e.lat,lng:e.lng}:null},async fetchCurrent(e){const t=`https://api.open-meteo.com/v1/forecast?latitude=${e.lat}&longitude=${e.lng}&current=temperature_2m,weather_code&temperature_unit=celsius&timezone=auto`,r=new AbortController,a=setTimeout(()=>r.abort(),5e3);try{const e=await fetch(t,{signal:r.signal});if(!e.ok)throw new Error(`Weather API returned ${e.status}`);const a=await e.json(),n=Math.round(a?.current?.temperature_2m),i=a?.current?.weather_code;if(!Number.isFinite(n))throw new Error("Weather API returned no temperature");return{tempC:n,icon:this.iconForCode(i)}}finally{clearTimeout(a)}},iconForCode:e=>0===e?"wb_sunny":[1,2,3].includes(e)?"wb_cloudy":[45,48].includes(e)?"foggy":[51,53,55,56,57].includes(e)?"grain":[61,63,65,66,67,80,81,82].includes(e)?"rainy":[71,73,75,77,85,86].includes(e)?"ac_unit":[95,96,99].includes(e)?"thunderstorm":"wb_cloudy"};
